// ── Segment Tree: build O(n), query O(log n), update O(log n) ──
class SegmentTree {
  #n;
  #tree;

  constructor(arr) {
    this.#n    = arr.length;
    this.#tree = new Array(4 * this.#n).fill(0);
    this.#build(arr, 1, 0, this.#n - 1);
  }

  // Bottom-up build: leaves get arr values, internals combine children
  #build(arr, v, start, end) {
    if (start === end) {
      this.#tree[v] = arr[start];
      return;
    }
    const mid = (start + end) >> 1;
    this.#build(arr, 2*v,   start, mid);
    this.#build(arr, 2*v+1, mid+1, end);
    this.#tree[v] = this.#tree[2*v] + this.#tree[2*v+1]; // combine step
  }

  // Point update: set arr[i] = val, fix all O(log n) ancestors
  update(i, val, v=1, start=0, end=this.#n-1) {
    if (start === end) {
      this.#tree[v] = val;
      return;
    }
    const mid = (start + end) >> 1;
    if (i <= mid) this.update(i, val, 2*v,   start, mid);
    else          this.update(i, val, 2*v+1, mid+1, end);
    this.#tree[v] = this.#tree[2*v] + this.#tree[2*v+1]; // recompute on the way up
  }

  // Range sum query [l..r]: three-case recursion
  query(l, r, v=1, start=0, end=this.#n-1) {
    if (r < start || end < l) return 0;                  // fully outside
    if (l <= start && end <= r) return this.#tree[v];    // fully inside
    const mid = (start + end) >> 1;
    return this.query(l, r, 2*v,   start, mid)
         + this.query(l, r, 2*v+1, mid+1, end);          // partial: recurse both
  }
}

const arr = [1, 2, 3, 4, 4, 5, 7, 10];
const seg = new SegmentTree(arr);

console.log(seg.query(2, 5));  // arr[2]+arr[3]+arr[4]+arr[5] = 3+4+4+5 = 16
seg.update(3, 10);             // change arr[3] from 4 to 10
console.log(seg.query(2, 5));  // 3+10+4+5 = 22
console.log(seg.query(0, 7));  // total sum: 1+2+3+10+4+5+7+10 = 42

// ── Lazy segment tree: range add + range sum, both O(log n) ──
class LazySegTree {
  #n; #sum; #lazy;
  constructor(arr) {
    this.#n = arr.length;
    this.#sum  = new Array(4 * this.#n).fill(0);
    this.#lazy = new Array(4 * this.#n).fill(0);  // pending "add" per node
    this.#build(arr, 1, 0, this.#n - 1);
  }
  #build(a, v, s, e) {
    if (s === e) { this.#sum[v] = a[s]; return; }
    const m = (s + e) >> 1;
    this.#build(a, 2 * v, s, m); this.#build(a, 2 * v + 1, m + 1, e);
    this.#sum[v] = this.#sum[2 * v] + this.#sum[2 * v + 1];
  }
  // Apply "add delta to every element" to a whole node in O(1)
  #apply(v, s, e, delta) {
    this.#sum[v]  += delta * (e - s + 1);
    this.#lazy[v] += delta;
  }
  // Push a pending tag to both children before descending
  #pushDown(v, s, e) {
    if (this.#lazy[v] === 0) return;
    const m = (s + e) >> 1;
    this.#apply(2 * v, s, m, this.#lazy[v]);
    this.#apply(2 * v + 1, m + 1, e, this.#lazy[v]);
    this.#lazy[v] = 0;
  }
  rangeAdd(l, r, delta, v = 1, s = 0, e = this.#n - 1) {
    if (r < s || e < l) return;                              // outside
    if (l <= s && e <= r) { this.#apply(v, s, e, delta); return; } // fully inside
    this.#pushDown(v, s, e);                                  // partial
    const m = (s + e) >> 1;
    this.rangeAdd(l, r, delta, 2 * v, s, m);
    this.rangeAdd(l, r, delta, 2 * v + 1, m + 1, e);
    this.#sum[v] = this.#sum[2 * v] + this.#sum[2 * v + 1];
  }
  query(l, r, v = 1, s = 0, e = this.#n - 1) {
    if (r < s || e < l) return 0;
    if (l <= s && e <= r) return this.#sum[v];
    this.#pushDown(v, s, e);
    const m = (s + e) >> 1;
    return this.query(l, r, 2 * v, s, m) + this.query(l, r, 2 * v + 1, m + 1, e);
  }
}

const lt = new LazySegTree([1, 2, 3, 4, 5, 6, 7, 8]);
console.log(lt.query(0, 7));   // 36
lt.rangeAdd(2, 5, 10);         // add 10 to indices 2..5
console.log(lt.query(0, 7));   // 76  (36 + 4 × 10)
console.log(lt.query(3, 4));   // 4+10 + 5+10 = 29
console.log(lt.query(5, 7));   // 6+10 + 7 + 8 = 31

// ── Fenwick Tree (Binary Indexed Tree) — 1-indexed ─────────────
class FenwickTree {
  #bit;
  #n;

  constructor(n) {
    this.#n   = n;
    this.#bit = new Array(n + 1).fill(0); // 1-indexed; bit[0] unused
  }

  // Build from an existing array in O(n): add each cell into its parent once.
  // (Calling update() n times would also work, but costs O(n log n).)
  static fromArray(arr) {
    const ft = new FenwickTree(arr.length);
    const bit = ft.#bit;
    for (let i = 1; i <= arr.length; i++) {
      bit[i] += arr[i - 1];              // shift to 1-indexed
      const parent = i + (i & -i);
      if (parent <= arr.length) bit[parent] += bit[i];
    }
    return ft;
  }

  // O(log n) — add delta to position i (1-indexed)
  // Walk UP the tree: i += i & (-i) moves to the next responsible ancestor
  update(i, delta) {
    for (; i <= this.#n; i += i & (-i))
      this.#bit[i] += delta;
  }

  // O(log n) — prefix sum of arr[1..i]
  // Walk DOWN the tree: i -= i & (-i) strips the lowest set bit
  query(i) {
    let sum = 0;
    for (; i > 0; i -= i & (-i))
      sum += this.#bit[i];
    return sum;
  }

  // O(log n) — range sum of arr[l..r] using prefix sum subtraction
  rangeQuery(l, r) {
    return this.query(r) - this.query(l - 1);
  }
}

// Worked example: array [1,2,3,4,4,5,7,10] (1-indexed positions 1-8)
const ft = FenwickTree.fromArray([1, 2, 3, 4, 4, 5, 7, 10]);

console.log(ft.query(3));          // prefix sum [1..3] = 1+2+3 = 6
console.log(ft.rangeQuery(3, 6));  // range sum [3..6] = 3+4+4+5 = 16

// Point update: arr[4] changes from 4 to 10 (delta = +6)
ft.update(4, 6);
console.log(ft.rangeQuery(3, 6));  // 3+10+4+5 = 22

// Trace of query(6):
// i=6 (110): sum += bit[6]; i = 6 - (6&-6) = 6-2 = 4
// i=4 (100): sum += bit[4]; i = 4 - (4&-4) = 4-4 = 0  -> stop
// bit[6] covers arr[5..6]; bit[4] covers arr[1..4] -> total is arr[1..6]
console.log(ft.query(6));  // 1+2+3+10+4+5 = 25

// ── Segment Tree for Range Minimum Query (RMQ) ─────────────────
// Swap + for Math.min, 0 (sum identity) for Infinity (min identity)
class RMQTree {
  #n; #tree;
  constructor(arr) {
    this.#n    = arr.length;
    this.#tree = new Array(4 * this.#n).fill(Infinity);
    this.#build(arr, 1, 0, this.#n - 1);
  }
  #build(arr, v, s, e) {
    if (s === e) { this.#tree[v] = arr[s]; return; }
    const m = (s + e) >> 1;
    this.#build(arr, 2*v,   s, m);
    this.#build(arr, 2*v+1, m+1, e);
    this.#tree[v] = Math.min(this.#tree[2*v], this.#tree[2*v+1]); // MIN instead of +
  }
  query(l, r, v=1, s=0, e=this.#n-1) {
    if (r < s || e < l) return Infinity;       // identity for MIN is Infinity
    if (l <= s && e <= r) return this.#tree[v];
    const m = (s + e) >> 1;
    return Math.min(
      this.query(l, r, 2*v,   s, m),
      this.query(l, r, 2*v+1, m+1, e)
    );
  }
}

// ── Fenwick Tree for Order Statistics (Count smaller / rank) ───
// A Fenwick tree indexed by VALUE can count occurrences and answer
// 'how many elements so far are <= x?' in O(log M) where M is value range.
class OrderStatsFenwick {
  #bit; #M;
  constructor(maxValue) {
    this.#M   = maxValue;
    this.#bit = new Array(maxValue + 1).fill(0);
  }
  insert(val) { for (let i=val; i<=this.#M; i+=i&-i) this.#bit[i]++; }
  countLeq(val) { let c=0; for (let i=val; i>0; i-=i&-i) c+=this.#bit[i]; return c; }
  // Count inversions in an array in O(n log n):
  // Process elements right-to-left; for each element x, count elements already
  // inserted that are LESS than x — those are inversions with x.
}

// RMQ example
const rmq = new RMQTree([3, 1, 4, 1, 5, 9, 2, 6]);
console.log(rmq.query(0, 4));  // min(3,1,4,1,5) = 1
console.log(rmq.query(4, 7));  // min(5,9,2,6)   = 2
console.log(rmq.query(5, 6));  // min(9,2)        = 2

// Order statistics: count inversions using Fenwick tree
// arr = [3,1,2], inversions = (3,1),(3,2) = 2
const ost = new OrderStatsFenwick(10);
let inversions = 0;
const testArr = [3, 1, 2];
for (let i = testArr.length - 1; i >= 0; i--) {
  inversions += ost.countLeq(testArr[i] - 1); // elements < testArr[i] already seen
  ost.insert(testArr[i]);
}
console.log(inversions); // 2
